import h5py, numpy as np, glob
def dec(a): return np.array([x.decode() if isinstance(x,bytes) else str(x) for x in a])
for fp in ['/app/data/sub-440956/sub-440956_ses-20190207T120657_behavior+ecephys+ogen.nwb',
           '/app/data/sub-480135/sub-480135_ses-20210302T140243_behavior+ecephys+ogen.nwb']:
    f=h5py.File(fp,'r'); t=f['intervals/trials']
    oc=dec(t['outcome'][:]); ti=dec(t['trial_instruction'][:])
    st=t['start_time'][:]; sp=t['stop_time'][:]
    go=f['acquisition/BehavioralEvents/go_start_times']['timestamps'][:]
    gostop=f['acquisition/BehavioralEvents/go_stop_times']['timestamps'][:]
    L=f['acquisition/BehavioralEvents/left_lick_times']['timestamps'][:]
    R=f['acquisition/BehavioralEvents/right_lick_times']['timestamps'][:]
    n=len(oc)
    pred=np.where(oc=='ignore','no lick',np.where(oc=='hit',ti,np.where(ti=='left','right','left')))
    obs=[]
    for i in range(n):
        lo,hi=go[i], sp[i]
        l=L[(L>=lo)&(L<=hi)]; r=R[(R>=lo)&(R<=hi)]
        if len(l)==0 and len(r)==0: obs.append('no lick')
        elif len(r)==0 or (len(l)>0 and l[0]<r[0]): obs.append('left')
        else: obs.append('right')
    obs=np.array(obs)
    print(fp.split('/')[-1], 'agree %.4f'%(pred==obs).mean())
    for a in ['left','right','no lick']:
        for b in ['left','right','no lick']:
            c=((pred==a)&(obs==b)).sum()
            if c and a!=b: print('   pred',a,'obs',b,c)
    print('  go duration', np.median(gostop-go), 'trialstop-go', np.median(sp-go))
EOF
python3 -u /tmp/choice.py

